        if(t.k){ if(mark[i] === t.k){ ok++; b.classList.add('ok'); } else { b.classList.add(mark[i] ? 'bad' : 'miss'); b.title = (cats.find(c => c[0] === t.k)||[])[1] || ''; if(cats.length > 1) b.insertAdjacentHTML('beforeend', `<sup>${esc(b.title)}</sup>`); } }
